css:
.switch {
  background-color: white;
  width: 233px;
  height: 88px;
  position: absolute;
  border-radius: 50px;
  border: 8px solid #ccc;
  cursor: pointer;
  user-select: none;
  display: inline-block;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.switch::before,
.switch::after {
  content: "";
  width: 50px;
  height: 50px;
  background-color: white;
  position: absolute;
  border-radius: 50%;
  top: -11%;
  left: -4%;
  transition:
    all 350ms cubic-bezier(0, 0.95, 0.38, 0.98),
    background 150ms ease;
  transform-origin: right center;
}
.switch::before {
  border: 19.2px solid rgb(76, 189, 226);
}
.switch::after {
  background: #fbd3e1;
  border: 19.2px solid #ff516e;
}
.gender-taggle:checked + .switch:before {
  background: #1cb7ea;
  transform: translateX(165%);
  border: 19.2px solid #ff516e;
}
.gender-taggle + .switch .female {
  color: #ff516e;
}
.gender-taggle:checked + .switch .male {
  color: #1cb7ea;
}
.gender-taggle + .switch .male {
  color: #ccc;
}
.gender-taggle:checked + .switch .female {
  color: #ccc;
}
.gender-taggle:checked + .switch:after {
  background: #d3f0fb;
  transform: translateX(165%);
  border: 19.2px solid #1cb7ea;
}
.female,
.male {
  position: absolute;
  font-weight: lighter;
  color: #ccc;
}
.female {
  z-index: -1;
  top: 3%;
  left: 3%;
  transform: rotate(180deg);
  font-size: 125px;
  font-weight: 400;
}
.male {
  z-index: -1;
  left: 87%;
  top: -97%;
  font-size: 70px;
  transform: rotate(-50deg);
}

@keyframes bounce {
  0%,
  20%,
  50%,
  80%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-30px);
  }
  60% {
    transform: translateY(-15px);
  }
}
